:root {
  --bg: #1a1d2b;
  --card: #23273a;
  --primary: #7c6ff0;
  --accent: #f0b46f;
  --highlight: #6ff0c0;
  --text: #f2f4ff;
  --muted: #a6adc8;
  --bar: #3f4560;
  --bar-active: var(--highlight);
  --bar-done: var(--accent);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at top, #2a2f4a 0%, var(--bg) 70%);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: 20px;
  padding: 24px;
  width: 100%;
  max-width: 640px;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.45);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

h1 {
  margin: 0;
  font-size: 1.5rem;
  letter-spacing: -0.02em;
}

.subtitle {
  margin: 0;
  color: var(--muted);
  font-size: 1rem;
  line-height: 1.4;
}

.bars {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 6px;
  height: 240px;
  padding: 12px;
  background: #1b1f30;
  border-radius: 14px;
  border: 1px solid #2f3450;
}

.bar {
  flex: 1 1 0;
  max-width: 48px;
  background: var(--bar);
  border-radius: 6px 6px 2px 2px;
  transition: height 0.2s ease, background 0.2s ease, transform 0.15s ease;
  min-height: 8px;
}

.bar.active {
  background: var(--bar-active);
  transform: translateY(-4px);
}

.bar.done {
  background: var(--bar-done);
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.btn {
  flex: 1 1 140px;
  padding: 14px 20px;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  color: #12141f;
  background: var(--primary);
  transition: transform 0.1s ease, filter 0.15s ease, box-shadow 0.15s ease;
  box-shadow: 0 4px 0 rgba(0, 0, 0, 0.25);
}

.btn:hover {
  filter: brightness(1.1);
}

.btn:focus-visible {
  outline: 3px solid var(--highlight);
  outline-offset: 2px;
}

.btn:active {
  transform: translateY(2px);
  box-shadow: 0 2px 0 rgba(0, 0, 0, 0.25);
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  filter: none;
  transform: none;
}

.btn-secondary {
  background: var(--accent);
}

.message {
  margin: 0;
  min-height: 1.5em;
  font-size: 1rem;
  color: var(--highlight);
  text-align: center;
  font-weight: 600;
}

@media (max-width: 420px) {
  .card {
    padding: 18px;
  }

  .bars {
    height: 200px;
    gap: 4px;
    padding: 8px;
  }

  h1 {
    font-size: 1.3rem;
  }
}

(function () {
  'use strict';

  const BAR_COUNT = 10;
  const MIN_HEIGHT = 10;
  const MAX_HEIGHT = 100;

  const barsContainer = document.getElementById('bars');
  const shuffleBtn = document.getElementById('shuffleBtn');
  const stepBtn = document.getElementById('stepBtn');
  const messageEl = document.getElementById('message');

  let values = [];
  let barElements = [];

  // Bubble sort state
  let i = 0; // pass index
  let j = 0; // comparison index within pass
  let sorted = false;

  function randomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  function generateRandomValues() {
    const arr = [];
    for (let k = 0; k < BAR_COUNT; k++) {
      arr.push(randomInt(MIN_HEIGHT, MAX_HEIGHT));
    }
    return arr;
  }

  function renderBars() {
    barsContainer.innerHTML = '';
    barElements = [];

    for (let k = 0; k < values.length; k++) {
      const bar = document.createElement('div');
      bar.className = 'bar';
      bar.style.height = values[k] + '%';
      bar.dataset.index = String(k);
      barsContainer.appendChild(bar);
      barElements.push(bar);
    }
  }

  function clearHighlights() {
    for (const el of barElements) {
      el.classList.remove('active');
    }
  }

  function markSorted() {
    for (const el of barElements) {
      el.classList.add('done');
    }
  }

  function clearSorted() {
    for (const el of barElements) {
      el.classList.remove('done');
    }
  }

  function setMessage(text) {
    messageEl.textContent = text;
  }

  function resetSortState() {
    i = 0;
    j = 0;
    sorted = false;
    clearHighlights();
    clearSorted();
    setMessage('');
    stepBtn.disabled = false;
  }

  function shuffle() {
    values = generateRandomValues();
    renderBars();
    resetSortState();
  }

  function updateBarHeight(index) {
    if (barElements[index]) {
      barElements[index].style.height = values[index] + '%';
    }
  }

  function step() {
    if (sorted) {
      return;
    }

    // If all passes are complete, mark sorted.
    if (i >= BAR_COUNT - 1) {
      sorted = true;
      clearHighlights();
      markSorted();
      setMessage('Sorted! The bars are in order.');
      stepBtn.disabled = true;
      return;
    }

    // Ensure j is within the unsorted portion of this pass.
    if (j >= BAR_COUNT - 1 - i) {
      i += 1;
      j = 0;
      if (i >= BAR_COUNT - 1) {
        sorted = true;
        clearHighlights();
        markSorted();
        setMessage('Sorted! The bars are in order.');
        stepBtn.disabled = true;
        return;
      }
    }

    const a = j;
    const b = j + 1;

    clearHighlights();
    barElements[a].classList.add('active');
    barElements[b].classList.add('active');

    if (values[a] > values[b]) {
      const tmp = values[a];
      values[a] = values[b];
      values[b] = tmp;
      updateBarHeight(a);
      updateBarHeight(b);
    }

    setMessage('Comparing positions ' + (a + 1) + ' and ' + (b + 1) + '.');

    j += 1;

    if (j >= BAR_COUNT - 1 - i) {
      i += 1;
      j = 0;
      if (i >= BAR_COUNT - 1) {
        sorted = true;
        clearHighlights();
        markSorted();
        setMessage('Sorted! The bars are in order.');
        stepBtn.disabled = true;
      }
    }
  }

  shuffleBtn.addEventListener('click', shuffle);
  stepBtn.addEventListener('click', step);

  // Initial setup
  values = generateRandomValues();
  renderBars();
  resetSortState();
})();
